#!/usr/bin/env Rscript
# DHARMa diagnostics for negative binomial models
# Reads cached data from Julia preprocessing, fits models, runs DHARMa
# Author: Generated by LLM
# Date: 2025

library(MASS)       # For glm.nb
library(DHARMa)     # For residual diagnostics
library(jsonlite)   # For reading metadata

# ============================================================================
# Configuration
# ============================================================================

CACHE_DIR <- "/scratch/yl998/.cache/dharma"
OUTPUT_DIR <- "/scratch/yl998/dharma_results"
N_SIMULATIONS <- 500  # DHARMa simulation count

# ============================================================================
# Functions
# ============================================================================

load_cache <- function() {
  "Load preprocessed data from Julia cache"
  
  # Check cache exists
  meta_file <- file.path(CACHE_DIR, "dharma_meta.json")
  if (!file.exists(meta_file)) {
    stop(sprintf("Cache not found. Run: julia julia_hybrid_pipeline.jl dharma <data_path>\nLooking for: %s", meta_file))
  }
  
  # Load metadata
  meta <- fromJSON(meta_file)
  cat("Loaded metadata from:", meta_file, "\n")
  
  # Load data
  data_file <- meta$data_file
  if (!file.exists(data_file)) {
    stop(sprintf("Data file not found: %s", data_file))
  }
  
  # Try CSV if ends with .csv, otherwise try arrow format
  if (grepl("\\.csv$", data_file)) {
    df <- read.csv(data_file, stringsAsFactors = FALSE)
  } else {
    # Try to use arrow if available, otherwise fall back to CSV
    if (requireNamespace("arrow", quietly = TRUE)) {
      df <- arrow::read_feather(data_file)
    } else {
      # Look for CSV version
      csv_file <- sub("\\.arrow$", ".csv", data_file)
      if (file.exists(csv_file)) {
        df <- read.csv(csv_file, stringsAsFactors = FALSE)
      } else {
        stop("Cannot read data file. Install 'arrow' package or provide CSV file.")
      }
    }
  }
  cat("Loaded data:", nrow(df), "rows,", ncol(df), "columns\n")
  cat("Sample fraction:", round(meta$sample_frac * 100, 1), "%\n\n")
  
  return(list(data = df, meta = meta))
}

build_formulas <- function(meta) {
  "Build model formulas based on MESF columns from metadata"
  
  # Base features
  climate <- c("bio01_std", "bio04_std", "bio12_std", "bio15_std")
  elevation <- c("elevation_std", "elevation_std_sq")
  mesf <- meta$mesf_columns
  base <- c(climate, elevation, mesf)
  
  # Biotic features
  biotic <- c("plants_richness_log", "vertebrates_richness_log")
  
  # Build formula strings - use R's interaction syntax
  formulas <- list(
    method1_null = paste("fungi_richness ~", paste(base, collapse = " + ")),
    method1_full = paste("fungi_richness ~", paste(c(base, biotic), collapse = " + ")),
    method2_continuous = paste("fungi_richness ~", paste(c(base, biotic), collapse = " + "), "+ bio04_std:plants_richness_log"),
    method2_categorical = paste("fungi_richness ~", paste(c(base, biotic), collapse = " + "), "+ I((bio04_std > 0) * (plants_richness_log > median(plants_richness_log)))")
  )
  
  return(formulas)
}

fit_and_diagnose <- function(formula_str, data, model_name) {
  "Fit negative binomial model and run DHARMa diagnostics"
  
  cat(paste(rep("=", 60), collapse = ""), "\n")
  cat("Model:", model_name, "\n")
  cat("Formula:", formula_str, "\n")
  cat(paste(rep("=", 60), collapse = ""), "\n")
  
  # Parse formula
  formula <- as.formula(formula_str)
  
  # Fit model
  cat("Fitting negative binomial model...\n")
  start_time <- Sys.time()
  model <- glm.nb(formula, data = data)
  fit_time <- difftime(Sys.time(), start_time, units = "secs")
  cat("  Fit time:", round(fit_time, 1), "seconds\n")
  cat("  AIC:", round(AIC(model), 2), "\n")
  cat("  Theta:", round(model$theta, 4), "\n")
  
  # DHARMa diagnostics
  cat("\nRunning DHARMa simulations (n=", N_SIMULATIONS, ")...\n", sep = "")
  start_time <- Sys.time()
  res <- simulateResiduals(
    fittedModel = model,
    n = N_SIMULATIONS,
    plot = FALSE,
    seed = 123
  )
  sim_time <- difftime(Sys.time(), start_time, units = "secs")
  cat("  Simulation time:", round(sim_time, 1), "seconds\n")
  
  # Run tests
  cat("\nDHARMa diagnostic tests:\n")
  
  # Uniformity test (KS test)
  test_unif <- testUniformity(res, plot = FALSE)
  cat("  Uniformity (KS):", sprintf("p = %.4f %s\n", 
                                    test_unif$p.value,
                                    ifelse(test_unif$p.value < 0.05, "❌", "✅")))
  
  # Dispersion test
  test_disp <- testDispersion(res, plot = FALSE)
  cat("  Dispersion:", sprintf("p = %.4f %s\n",
                               test_disp$p.value,
                               ifelse(test_disp$p.value < 0.05, "❌", "✅")))
  
  # Outliers test
  test_out <- testOutliers(res, plot = FALSE)
  cat("  Outliers:", sprintf("p = %.4f %s\n",
                             test_out$p.value,
                             ifelse(test_out$p.value < 0.05, "❌", "✅")))
  
  # Zero-inflation test (important for count data)
  test_zero <- testZeroInflation(res, plot = FALSE)
  cat("  Zero-inflation:", sprintf("p = %.4f %s\n",
                                   test_zero$p.value,
                                   ifelse(test_zero$p.value < 0.05, "❌", "✅")))
  
  # Quantile test (checks for deviations at specific quantiles)
  test_quant <- testQuantiles(res, plot = FALSE)
  cat("  Quantiles:", sprintf("p = %.4f %s\n",
                              test_quant$p.value,
                              ifelse(test_quant$p.value < 0.05, "❌", "✅")))
  
  # Overall assessment
  all_pass <- all(c(test_unif$p.value, test_disp$p.value, test_out$p.value,
                    test_zero$p.value, test_quant$p.value) > 0.05)
  
  cat("\n  Overall:", ifelse(all_pass, "✅ PASS", "❌ ISSUES DETECTED"), "\n")
  
  # Return results (don't store model object)
  return(list(
    model_name = model_name,
    aic = AIC(model),
    theta = model$theta,
    n_obs = nobs(model),
    tests = list(
      uniformity = test_unif$p.value,
      dispersion = test_disp$p.value,
      outliers = test_out$p.value,
      zero_inflation = test_zero$p.value,
      quantiles = test_quant$p.value
    ),
    dharma_object = res,  # Keep DHARMa object for plotting
    all_pass = all_pass,
    fit_time = as.numeric(fit_time),
    sim_time = as.numeric(sim_time)
  ))
}

save_dharma_plots <- function(results, output_dir) {
  "Save DHARMa diagnostic plots - selective based on model type"
  
  dir.create(output_dir, showWarnings = FALSE, recursive = TRUE)
  
  for (result in results) {
    # Always create main diagnostic plot
    plot_file <- file.path(output_dir, paste0(result$model_name, "_dharma.png"))
    
    png(plot_file, width = 12, height = 8, units = "in", res = 150)
    par(mfrow = c(2, 3))
    
    # Standard DHARMa plot (QQ and residuals vs predicted)
    plot(result$dharma_object, main = result$model_name)
    
    # Additional diagnostic plots
    testUniformity(result$dharma_object)
    testDispersion(result$dharma_object)
    testZeroInflation(result$dharma_object)
    
    dev.off()
    cat("Plot saved:", plot_file, "\n")
    
    # Only create individual residual plots for method1_full
    if (result$model_name == "method1_full") {
      save_all_residual_plots(result, output_dir)
    } else if (result$model_name == "method2_continuous") {
      # Create plots for key continuous interaction variables
      save_key_variable_plots(result, output_dir, c("bio04_std", "plants_richness_log"))
    } else if (result$model_name == "method2_categorical") {
      # Create plots for key categorical model variables
      save_key_variable_plots(result, output_dir, c("bio04_std", "plants_richness_log"))
    }
  }
}

save_all_residual_plots <- function(result, output_dir) {
  "Save all residual plots for method1_full"
  
  dharma_obj <- result$dharma_object
  model_data <- dharma_obj$fittedModel$model
  
  if (is.null(model_data)) {
    cat("  Cannot extract model data for residual plots\n")
    return()
  }
  
  # Get all predictor names (exclude response)
  response_name <- as.character(dharma_obj$fittedModel$formula[[2]])
  predictor_names <- setdiff(names(model_data), response_name)
  
  # Create individual plot for each predictor
  for (pred in predictor_names) {
    plot_file <- file.path(output_dir, paste0(result$model_name, "_", pred, ".png"))
    
    png(plot_file, width = 800, height = 600, units = "px", res = 100)
    plotResiduals(dharma_obj, form = model_data[[pred]], 
                  xlab = pred, main = paste(result$model_name, "-", pred))
    dev.off()
  }
  
  cat("  Created", length(predictor_names), "residual plots\n")
}

save_key_variable_plots <- function(result, output_dir, var_names) {
  "Save plots for key variables"
  
  dharma_obj <- result$dharma_object
  model_data <- dharma_obj$fittedModel$model
  
  if (is.null(model_data)) {
    cat("  Cannot extract model data for variable plots\n")
    return()
  }
  
  for (var_name in var_names) {
    if (var_name %in% names(model_data)) {
      plot_file <- file.path(output_dir, paste0(result$model_name, "_", var_name, ".png"))
      
      png(plot_file, width = 800, height = 600, units = "px", res = 100)
      plotResiduals(dharma_obj, form = model_data[[var_name]], 
                    xlab = var_name, main = paste(result$model_name, "-", var_name))
      dev.off()
    }
  }
  cat("  Created plots for key variables:", paste(var_names, collapse = ", "), "\n")
}


# ============================================================================
# Main execution
# ============================================================================

main <- function() {
  cat("\n")
  cat(paste(rep("=", 60), collapse = ""), "\n")
  cat("DHARMa RESIDUAL DIAGNOSTICS FOR NEGATIVE BINOMIAL MODELS\n")
  cat(paste(rep("=", 60), collapse = ""), "\n\n")
  
  # Load cached data
  cache <- load_cache()
  df <- cache$data
  meta <- cache$meta
  
  # Build formulas from metadata
  formulas <- build_formulas(meta)
  
  # Fit and diagnose all 4 models
  results <- list()
  
  # Method 1 models
  results[[1]] <- fit_and_diagnose(
    formulas$method1_null,
    df,
    "method1_null"
  )
  
  results[[2]] <- fit_and_diagnose(
    formulas$method1_full,
    df,
    "method1_full"
  )
  
  # Method 2 models
  # Note: Julia already created interaction terms during preprocessing
  results[[3]] <- fit_and_diagnose(
    formulas$method2_continuous,
    df,
    "method2_continuous"
  )
  
  results[[4]] <- fit_and_diagnose(
    formulas$method2_categorical,
    df,
    "method2_categorical"
  )
  
  # Summary
  cat("\n")
  cat(paste(rep("=", 60), collapse = ""), "\n")
  cat("SUMMARY OF DHARMA DIAGNOSTICS\n")
  cat(paste(rep("=", 60), collapse = ""), "\n\n")
  
  summary_df <- data.frame(
    Model = sapply(results, function(x) x$model_name),
    AIC = sapply(results, function(x) round(x$aic, 1)),
    Theta = sapply(results, function(x) round(x$theta, 3)),
    Uniformity = sapply(results, function(x) sprintf("%.3f", x$tests$uniformity)),
    Dispersion = sapply(results, function(x) sprintf("%.3f", x$tests$dispersion)),
    Outliers = sapply(results, function(x) sprintf("%.3f", x$tests$outliers)),
    ZeroInfl = sapply(results, function(x) sprintf("%.3f", x$tests$zero_inflation)),
    Overall = sapply(results, function(x) ifelse(x$all_pass, "PASS", "FAIL"))
  )
  
  print(summary_df, row.names = FALSE)
  
  # Save plots
  cat("\nSaving diagnostic plots...\n")
  save_dharma_plots(results, OUTPUT_DIR)
  
  # Save summary to JSON
  summary_file <- file.path(OUTPUT_DIR, "dharma_summary.json")
  summary_json <- lapply(results, function(x) {
    list(
      model = x$model_name,
      aic = x$aic,
      theta = x$theta,
      n_obs = x$n_obs,
      tests = x$tests,
      pass = x$all_pass,
      timing = list(fit = x$fit_time, simulation = x$sim_time)
    )
  })
  write_json(summary_json, summary_file, pretty = TRUE)
  cat("\nSummary saved:", summary_file, "\n")
  
  cat("\n✅ DHARMa diagnostics complete!\n\n")
  
  # Return status
  n_pass <- sum(sapply(results, function(x) x$all_pass))
  if (n_pass == length(results)) {
    cat("All models passed DHARMa diagnostics.\n")
  } else {
    cat(sprintf("⚠ %d/%d models showed diagnostic issues.\n", 
                length(results) - n_pass, length(results)))
  }
}

# Run if executed directly
if (!interactive()) {
  main()
}